import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.BQq6mqvm.js";const u=JSON.parse('{"title":"用户管理","description":"","frontmatter":{},"headers":[],"relativePath":"admin/users.md","filePath":"admin/users.md","lastUpdated":1790385461000}'),s={name:"admin/users.md"};function l(n,t,i,d,h,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h1><p>在左侧菜单进入<strong>管理 → 用户管理</strong>。这里可以创建账号、调整角色、重置密码、停用或删除账号。</p><h2 id="创建账号" tabindex="-1">创建账号 <a class="header-anchor" href="#创建账号" aria-label="Permalink to &quot;创建账号&quot;">​</a></h2><p>点击右上角<strong>新建账号</strong>，填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>工号</td><td>登录用，<strong>唯一</strong>，创建后不可修改，不能含空格或斜杠</td></tr><tr><td>姓名</td><td>用于显示，允许重名</td></tr><tr><td>角色</td><td>普通用户 / 管理员</td></tr><tr><td>初始密码</td><td>至少 6 位，建议告知本人后要求其首次登录修改</td></tr></tbody></table><p>创建成功后，系统会自动为该成员建立独立目录，并把相对路径记录到账号信息里。</p><h2 id="修改账号" tabindex="-1">修改账号 <a class="header-anchor" href="#修改账号" aria-label="Permalink to &quot;修改账号&quot;">​</a></h2><p>点击某一行的<strong>编辑</strong>，可以修改姓名、角色和启用状态。<strong>工号不可修改</strong>。</p><p>把「启用」关闭后，该账号<strong>立即无法登录</strong>，已登录的会话也会失效。</p><h2 id="重置密码" tabindex="-1">重置密码 <a class="header-anchor" href="#重置密码" aria-label="Permalink to &quot;重置密码&quot;">​</a></h2><p>点击<strong>重置密码</strong>，输入新密码即可。重置后该成员已登录的所有设备会立即失效，需要用新密码重新登录。</p><h2 id="停用与删除" tabindex="-1">停用与删除 <a class="header-anchor" href="#停用与删除" aria-label="Permalink to &quot;停用与删除&quot;">​</a></h2><p><strong>停用</strong>（编辑 → 关闭启用）适合临时禁止登录，账号和文件都保留。</p><p><strong>删除</strong>账号时会遇到两种情况：</p><ul><li>该账号<strong>名下还有文件</strong>：系统会提示文件数量，并拒绝直接删除。</li><li>需要勾选「同时彻底删除文件」才能删除，此时其<strong>全部文件会永久删除</strong>，不可恢复。</li></ul><div class="danger custom-block"><p class="custom-block-title">删除前请确认</p><p>删除账号会连同其目录一起移除。如果只是想收回访问权限，请使用<strong>停用</strong>而不是删除。</p></div><h2 id="保护措施" tabindex="-1">保护措施 <a class="header-anchor" href="#保护措施" aria-label="Permalink to &quot;保护措施&quot;">​</a></h2><p>为避免把自己锁在系统外，以下操作会被拒绝：</p><ul><li>删除自己的账号</li><li>停用自己的账号</li><li>把自己降级为普通用户</li><li>删除或停用系统中<strong>最后一个</strong>可用的管理员</li></ul><h2 id="列表说明" tabindex="-1">列表说明 <a class="header-anchor" href="#列表说明" aria-label="Permalink to &quot;列表说明&quot;">​</a></h2><p>列表显示每位成员的工号、姓名、角色、状态、文件数、占用空间、目录和最后登录时间，支持按工号或姓名搜索。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./settings">系统管理</a></li><li><a href="./files">文件与回收站</a></li></ul>',23)])])}const g=a(s,[["render",l]]);export{u as __pageData,g as default};
